"""Normalize and aggregate stock quantities by SKU."""

import argparse
import csv
import json
import re


def summarize(rows):
    totals = {}
    for row in rows:
        status = row.get("status", "")
        if status is None:
            status = ""
        if not isinstance(status, str):
            raise ValueError("status must be active or archived")
        status = status.strip().lower() or "active"
        if status == "archived":
            continue
        if status != "active":
            raise ValueError("status must be active or archived")
        sku = row.get("sku")
        if not isinstance(sku, str) or not sku.strip():
            raise ValueError("sku must be a non-empty string")
        sku = sku.strip().lower()
        quantity = row.get("quantity")
        if isinstance(quantity, str) and re.fullmatch(r"[+-]?[0-9]+", quantity.strip()):
            quantity = int(quantity, 10)
        if type(quantity) is not int or quantity < 0:
            raise ValueError("quantity must be a non-negative base10 integer")
        totals[sku] = totals.get(sku, 0) + quantity
    return [{"sku": sku, "quantity": totals[sku]} for sku in sorted(totals)]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input", help="UTF-8 CSV (optional BOM) with sku,quantity and optional status")
    args = parser.parse_args()
    with open(args.input, encoding="utf-8-sig", newline="") as source:
        rows = csv.DictReader(source)
        fields = rows.fieldnames
        if fields is not None and (
            len(fields) != len(set(fields))
            or set(fields) not in ({"sku", "quantity"}, {"sku", "quantity", "status"})
        ):
            raise ValueError("CSV header must contain sku,quantity and optional status")
        result = summarize(rows)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

