import argparse
import csv
import json
import re


def summarize(rows):
    totals = {}
    for row in rows:
        status = row.get("status")
        if status is None:
            status = "active"
        if not isinstance(status, str):
            raise ValueError("status must be active or archived")
        status = status.strip().lower() or "active"
        if status == "archived":
            continue
        if status != "active":
            raise ValueError("status must be active or archived")
        sku = row.get("sku")
        if not isinstance(sku, str) or not sku.strip():
            raise ValueError("sku must be a non-empty string")
        sku = sku.strip().lower()
        quantity = row.get("quantity")
        if isinstance(quantity, str):
            if not re.fullmatch(r"[+-]?[0-9]+", quantity.strip()):
                raise ValueError("quantity must be a non-negative integer")
            quantity = int(quantity, 10)
        if type(quantity) is not int or quantity < 0:
            raise ValueError("quantity must be a non-negative integer")
        totals[sku] = totals.get(sku, 0) + quantity
    return [{"sku": sku, "quantity": totals[sku]} for sku in sorted(totals)]


def main():
    parser = argparse.ArgumentParser(description="Summarize active stock from a UTF-8 CSV (BOM supported).")
    parser.add_argument("input", metavar="INPUT.csv")
    args = parser.parse_args()
    try:
        with open(args.input, encoding="utf-8-sig", newline="") as source:
            rows = csv.DictReader(source)
            if rows.fieldnames is not None and not {"sku", "quantity"}.issubset(rows.fieldnames):
                raise ValueError("CSV header must include sku,quantity")
            result = summarize(rows)
    except (OSError, ValueError, csv.Error) as error:
        parser.error(str(error))
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
